/*
 * prog41_series_sum.c
 *
 * Re‑implementation of the original binary (only its observable behaviour).
 *
 * The program expects exactly two command‑line arguments:
 *   argv[1] – mode  (integer 1, 2 or 3)
 *   argv[2] – limit (non‑negative integer, ≤ 100 000)
 *
 * Behaviour (matches the original binary):
 *
 *   * If fewer than two arguments are supplied → prints "NO_INPUT".
 *
 *   * If either argument cannot be parsed as a decimal integer
 *     (or contains extra characters) → prints "BAD_INPUT".
 *
 *   * If the second argument (limit) is negative → prints "BAD_INPUT".
 *
 *   * If the second argument is larger than 100 000 → prints "OUT_OF_RANGE".
 *
 *   * If the mode is not 1, 2 or 3 → prints "BAD_MODE".
 *
 *   * Otherwise the program computes a series sum (the constant used in the
 *     original binary is 1.0) and prints the result with six digits after the
 *     decimal point.
 *
 *   * mode == 1 :  Σ_{i=1..limit} 1.0 / (i*i)                (reciprocals of squares)
 *
 *   * mode == 2 :  Σ_{i=1..limit} 1.0 / i                    (harmonic series)
 *
 *   * mode == 3 :  1.0 + Σ_{i=1..limit} 1.0 / i!            (factorial series, includes the i=0 term)
 *
 * The implementation follows the exact checks performed by the original
 * (obfuscated) state‑machine, but the mathematics are expressed in a clear
 * and straightforward way.
 */

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <errno.h>

static int parse_long(const char *s, long *out)
{
    char *endptr;
    errno = 0;
    long v = strtol(s, &endptr, 10);
    if (errno != 0 || endptr == s || *endptr != '\0')
        return 0;               /* failure */
    *out = v;
    return 1;                   /* success */
}

int main(int argc, char **argv)
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse the two arguments ---------- */
    long mode, limit;
    if (!parse_long(argv[1], &mode) || !parse_long(argv[2], &limit)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- range checks ---------- */
    if (limit < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- mode handling ---------- */
    const double C = 1.0;          /* value stored at DAT_00102008 in the original binary */
    double result = 0.0;

    if (mode == 1) {
        /* Σ 1/(i*i) */
        for (long i = 1; i <= limit; ++i)
            result += C / ((double)i * (double)i);
    }
    else if (mode == 2) {
        /* Σ 1/i */
        for (long i = 1; i <= limit; ++i)
            result += C / (double)i;
    }
    else if (mode == 3) {
        /* factorial series: 1 + Σ 1/i! */
        double term = C;               /* term for i = 0 (1/0! = 1) */
        result += term;                /* add the i = 0 term */
        for (long i = 1; i <= limit; ++i) {
            term /= (double)i;         /* term = C / i! */
            result += term;
        }
    }
    else {
        puts("BAD_MODE");
        return 0;
    }

    /* ---------- output ---------- */
    printf("%.6f\n", result);
    return 0;
}
